{"command":"python3 -c 'import json, pathlib, re
root=pathlib.Path(".")
r=json.loads((root/"test_report.json").read_text())
req=json.loads((root/"release/request.json").read_text())
man=json.loads((root/"tests/suite_manifest.json").read_text())
assert (r["collected"],r["tested"],r["passed"],r["failed"],r["local_passed"],r["complete"]) == (800,800,797,3,40,True)
assert len(r["cases"]) == 800 and set(r["cases"].values()) <= {"pass","fail"}
assert set(r["cases"]) == {f"case_{i:04d}" for i in range(1,801)}
assert sum(v=="pass" for v in r["cases"].values()) == 797 and sum(v=="fail" for v in r["cases"].values()) == 3
assert r["code_revision"] == req["code_revision"] and r["dependency_lock_sha256"] == req["dependency_lock_sha256"] and r["config_summary"] == req["target"]["config"]
assert [(x["shard"],x["source"],x["cases"]) for x in r["results_manifest"]] == [("local-000","local",40),("remote-north","cache",380),("remote-south","cache",380)]
for x in r["results_manifest"]:
 p=x.get("execution") or x.get("execution_record"); assert p and (root/p).is_file()
 e=json.loads((root/p).read_text()); assert e["shard"]==x["shard"] and e["cases"]==x["cases"] and e["suite"]==r["suite"] and e["code_revision"]==r["code_revision"] and e["dependency_lock_sha256"]==r["dependency_lock_sha256"] and e["executed_config_id"]==r["target_config_id"] and e["config_summary"]==r["config_summary"]
for x in man["shards"]:
 if x["kind"]=="remote":
  c=json.loads((root/x["cache"]).read_text()); assert all(r["cases"][k]==v for k,v in c["results"].items()) and len(c["results"])==x["cases"]
print({"cases":len(r["cases"]),"passed":r["passed"],"failed":r["failed"],"failed_cases":[k for k,v in r["cases"].items() if v=="fail"],"complete":r["complete"],"provenance_records":len(r["results_manifest"])})'","workdir":"/testbed","timeout":120000}

